UPDATE public.teams SET kit_colour='#00A651',profile_version=profile_version+1 WHERE id='bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3';
UPDATE public.teams SET name='Kabul Commandos',profile_version=profile_version+1 WHERE id='f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c';
INSERT INTO public.team_fixture_notes(team_id,notes) VALUES('bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3','Organiser confirmed 11 November 2026: Dream Team must use Court 1 for all unplayed fixtures. Avoid 21:00 except against Umoja Stars, which remains at 21:00. Existing 19:00/19:40-only availability against other opponents is retained. Green kit.')
ON CONFLICT(team_id) DO UPDATE SET notes=excluded.notes || E'\n\nEarlier recorded context: ' || public.team_fixture_notes.notes;
UPDATE public.team_fixture_notes SET notes=replace(notes,'Hakim''s Team','Kabul Commandos') WHERE team_id='f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c';
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM dk_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE CASE WHEN b.id IN(select id from dk_baseline) THEN
 (to_jsonb(b)-'court'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(f)-'court'-'schedule_version'-'updated_at') OR f.court<>3-b.court OR f.schedule_version<>b.schedule_version+2
 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(f) END) THEN RAISE EXCEPTION 'Unexpected fixture change';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures f WHERE f.publication_state='published' AND f.schedule_status='scheduled' AND 'bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3' IN(f.home_team_id,f.away_team_id) AND NOT EXISTS(SELECT 1 FROM public.result_versions r WHERE r.fixture_id=f.id) AND f.court<>1) THEN RAISE EXCEPTION 'Dream Team court rule failed';END IF;
 IF EXISTS(SELECT 1 FROM dk_teams_before b FULL JOIN public.teams t USING(id) WHERE CASE WHEN b.id='bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3' THEN (to_jsonb(b)-'kit_colour'-'profile_version'-'updated_at') IS DISTINCT FROM (to_jsonb(t)-'kit_colour'-'profile_version'-'updated_at') OR t.kit_colour<>'#00A651' OR t.profile_version<>b.profile_version+1
 WHEN b.id='f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c' THEN (to_jsonb(b)-'name'-'profile_version'-'updated_at') IS DISTINCT FROM (to_jsonb(t)-'name'-'profile_version'-'updated_at') OR t.name<>'Kabul Commandos' OR t.profile_version<>b.profile_version+1
 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(t) END) THEN RAISE EXCEPTION 'Unexpected team change';END IF;
 IF EXISTS(SELECT 1 FROM dk_results_before b FULL JOIN public.result_versions r USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(r)) THEN RAISE EXCEPTION 'Results changed';END IF;
 IF EXISTS(SELECT 1 FROM dk_preferences_before b FULL JOIN public.team_kickoff_preferences p USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(p)) THEN RAISE EXCEPTION 'Availability rows changed';END IF;
 IF EXISTS(SELECT 1 FROM dk_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
END $$;
SELECT txid_current() AS transaction_id,(SELECT count(*) FROM dk_baseline) AS changed_fixtures;
COMMIT;
